#!/usr/bin/env python3
"""Compute the CSX-066_Q2 numeric diagnosis ground truth."""

from __future__ import annotations

import json
import re
from datetime import date
from html import unescape
from pathlib import Path
from typing import Any


TASK_ID = "CSX-066_Q2"
EVENT_ID = "CSX-066"


def package_dir() -> Path:
    return (
        Path(__file__).resolve().parents[3]
        / "event_packages"
        / "standard_event_packages"
        / "packages"
        / EVENT_ID
    )


def read_json(root: Path, rel_path: str) -> Any:
    return json.loads((root / rel_path).read_text(encoding="utf-8"))


def visible_text(html: str) -> str:
    html = re.sub(r"<(script|style).*?</\1>", " ", html, flags=re.S | re.I)
    html = re.sub(r"<[^>]+>", " ", html)
    return unescape(re.sub(r"\s+", " ", html)).strip()


def report_text(root: Path) -> str:
    rel_path = "data/other/other_003_01_NASA_Earth_Observatory_-_Floods_swamp_Sudan.html.html"
    return visible_text((root / rel_path).read_text(encoding="utf-8", errors="replace"))


def inclusive_days(start: str, end: str) -> int:
    return (date.fromisoformat(end) - date.fromisoformat(start)).days + 1


def day_index(start: str, target: str) -> int:
    return (date.fromisoformat(target) - date.fromisoformat(start)).days + 1


def precipitation_metrics(era5: dict[str, Any], gpm: dict[str, Any], chirps: dict[str, Any]) -> dict[str, Any]:
    products = {
        "era5_land": {
            "mean_mm": era5["stats"]["precipitation_sum_mm_mean"],
            "max_mm": era5["stats"]["precipitation_sum_mm_max"],
        },
        "gpm_imerg": {
            "mean_mm": gpm["stats"]["gpm_event_precip_mm_mean"],
            "max_mm": gpm["stats"]["gpm_event_precip_mm_max"],
        },
        "chirps": {
            "mean_mm": chirps["stats"]["chirps_event_precip_mm_mean"],
            "max_mm": chirps["stats"]["chirps_event_precip_mm_max"],
        },
    }
    for values in products.values():
        values["max_to_mean_ratio"] = values["max_mm"] / values["mean_mm"]

    rounded_products = {
        name: {
            "mean_mm": round(values["mean_mm"], 3),
            "max_mm": round(values["max_mm"], 3),
            "max_to_mean_ratio": round(values["max_to_mean_ratio"], 3),
        }
        for name, values in products.items()
    }
    largest = max(products.items(), key=lambda item: item[1]["max_to_mean_ratio"])[0]

    return {
        "products": rounded_products,
        "ratios_by_product": {
            name: values["max_to_mean_ratio"] for name, values in rounded_products.items()
        },
        "largest_product": largest,
        "satellite_daily_max_gap_mm": round(abs(products["gpm_imerg"]["max_mm"] - products["chirps"]["max_mm"]), 3),
    }


def state_fraction(text: str) -> float:
    match = re.search(
        r"displaced as many as ([\d,]+) people across (\d+) of Sudan\S*\s+(\d+) states",
        text,
    )
    if not match:
        raise ValueError("Could not extract affected-state count from report text")
    affected_states = int(match.group(2))
    total_states = int(match.group(3))
    return round(affected_states / total_states, 3)


def facility_metrics(root: Path) -> dict[str, Any]:
    hdx = read_json(root, "data/exposure_impact/exposure_impact_002_HDX_Sudan_Arbaat_flood_package_search.json")
    result = hdx["result"]["results"][0]
    notes = result["notes"]

    unaffected_names = ["Abunqarah", "Kdoweeb", "Tobler", "Edbye", "Tedrbai Family Health Centers"]
    likely_names = [
        "Tedrbai",
        "Hit Wasat",
        "Tamli",
        "Agoamet Srarah",
        "Tegilo",
        "Kelkoy",
        "Mostehliland Shalhout",
    ]
    missing = [name for name in unaffected_names + likely_names if name not in notes]
    if missing:
        raise ValueError(f"Could not verify facility names in local assessment notes: {missing}")

    likely_count = len(likely_names)
    unaffected_count = len(unaffected_names)
    total = likely_count + unaffected_count

    return {
        "assessment_date": result["dataset_date"][1:11],
        "overflow_dates": ["2024-08-30", "2024-08-31"],
        "likely_affected": likely_count,
        "apparently_unaffected": unaffected_count,
        "total_listed": total,
        "likely_fraction": round(likely_count / total, 3),
        "likely_to_unaffected_ratio": round(likely_count / unaffected_count, 3),
    }


def timing_metrics(start: str, end: str, overflow_dates: list[str], assessment_date: str) -> dict[str, Any]:
    event_days = inclusive_days(start, end)
    overflow_indices = [day_index(start, item) for item in overflow_dates]
    assessment_index = day_index(start, assessment_date)
    return {
        "event_window_days": event_days,
        "overflow_day_indices": overflow_indices,
        "overflow_fractions": [round(index / event_days, 3) for index in overflow_indices],
        "assessment_day_index": assessment_index,
        "assessment_fraction": round(assessment_index / event_days, 3),
        "overflow_to_assessment_lags_days": [
            (date.fromisoformat(assessment_date) - date.fromisoformat(item)).days for item in overflow_dates
        ],
    }


def main() -> None:
    root = package_dir()
    event = read_json(root, "metadata/event.json")
    anchor = read_json(
        root,
        "data/event_reports/event_reports_003_Locked_event_anchor_2024_Sudan_floods_and_Arba_at_Dam_flood.json",
    )
    era5 = read_json(root, "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json")
    gpm = read_json(root, "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json(root, "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json")
    population = read_json(root, "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json")

    window = anchor["temporal_window"]
    precip = precipitation_metrics(era5, gpm, chirps)
    facilities = facility_metrics(root)
    timing = timing_metrics(
        window["start_date"],
        window["end_date"],
        facilities["overflow_dates"],
        facilities["assessment_date"],
    )
    population_sum = population["population_sum"]["population"]
    denominator = {
        "affected_state_fraction": state_fraction(report_text(root)),
        "population_per_listed_facility": round(population_sum / facilities["total_listed"], 2),
        "population_per_likely_affected_facility": round(population_sum / facilities["likely_affected"], 2),
        "use_as_driver": False,
    }

    answer = "rainfall_late_overflow_facility_exposure"
    primary_gt = {
        "answer": answer,
        "precipitation_concentration": {
            "ratios_by_product": precip["ratios_by_product"],
            "largest_product": precip["largest_product"],
            "satellite_daily_max_gap_mm": precip["satellite_daily_max_gap_mm"],
        },
        "timing": {
            "event_window_days": timing["event_window_days"],
            "overflow_day_indices": timing["overflow_day_indices"],
            "overflow_fractions": timing["overflow_fractions"],
            "assessment_day_index": timing["assessment_day_index"],
            "assessment_fraction": timing["assessment_fraction"],
            "overflow_to_assessment_lags_days": timing["overflow_to_assessment_lags_days"],
        },
        "facility_exposure": {
            "likely_affected": facilities["likely_affected"],
            "apparently_unaffected": facilities["apparently_unaffected"],
            "total_listed": facilities["total_listed"],
            "likely_fraction": facilities["likely_fraction"],
            "likely_to_unaffected_ratio": facilities["likely_to_unaffected_ratio"],
        },
        "denominator_check": {
            "affected_state_fraction": denominator["affected_state_fraction"],
            "population_per_listed_facility": denominator["population_per_listed_facility"],
            "population_per_likely_affected_facility": denominator["population_per_likely_affected_facility"],
            "use_as_driver": False,
        },
        "decision": "Use the concentrated-rainfall, late-overflow, facility-exposure diagnostic; do not let a single maximum rainfall cell or population denominator replace the local timing and exposure calculation.",
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "Answer label and JSON shape",
                "points": 3,
                "description": "Returns the requested compact JSON fields and the answer label rainfall_late_overflow_facility_exposure or a clear equivalent.",
                "partial_credit": "Award 1-2 points for a mostly complete structure with one or two missing fields, or for a label that omits one component.",
            },
            {
                "name": "Precipitation concentration arithmetic",
                "points": 4,
                "description": "Computes the three max-to-mean precipitation ratios, identifies gpm_imerg as largest, and gives the 87.786 mm satellite-daily maximum gap within tolerance.",
                "partial_credit": "Award 2-3 points for correct formulas with one wrong or missing value; award 1 point for using max divided by mean but not completing the diagnostic.",
            },
            {
                "name": "Overflow timing reconstruction",
                "points": 4,
                "description": "Computes the 24-day event window, overflow day indices 18 and 19, fractions 0.750 and 0.792, assessment day 21, fraction 0.875, and lags 3 and 2 days.",
                "partial_credit": "Award 2-3 points for correct dates and lags with one inclusive-index or rounding error; award 1 point for recognizing the late-window sequence without complete values.",
            },
            {
                "name": "Facility exposure ratios",
                "points": 3,
                "description": "Computes 7 likely affected, 5 apparently unaffected, 12 total listed, likely fraction 0.583, and likely-to-unaffected ratio 1.400.",
                "partial_credit": "Award 1-2 points for correct counts with a missing ratio or a small arithmetic error.",
            },
            {
                "name": "Denominator check",
                "points": 3,
                "description": "Computes affected-state fraction 0.722, population per listed facility 22494.38, population per likely affected facility 38561.79, and sets use_as_driver to false.",
                "partial_credit": "Award 1-2 points for computing the denominators but not clearly treating them as non-controlling for the local diagnosis.",
            },
            {
                "name": "Calculation-linked decision",
                "points": 2,
                "description": "Connects rainfall concentration, late overflow timing, and facility exposure while rejecting single-cell rainfall and population-denominator substitutes.",
                "partial_credit": "Award 1 point for a correct final decision that omits one computed support or one rejected substitute.",
            },
            {
                "name": "Concise computed interpretation",
                "points": 1,
                "description": "Keeps the interpretation limited to what the diagnostic calculates and avoids extra assertions about exact flood depth, velocity, mortality, or facility service status.",
                "partial_credit": "Award 0.5 points for minor extra wording that does not change the answer.",
            },
        ],
    }

    output = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "target_family": "flood_timing_exposure_diagnostic",
        "primary_gt": primary_gt,
        "key_values": {
            "event": {
                "name": event["event_name"],
                "hazard_family": event["hazard_family"],
                "window": f"{window['start_date']} to {window['end_date']}",
            },
            "precipitation_concentration": precip,
            "timing": timing,
            "facility_exposure": {
                key: value
                for key, value in facilities.items()
                if key not in {"overflow_dates", "assessment_date"}
            },
            "denominator_check": denominator,
            "tolerances": {"ratio": 0.002, "mm": 0.005, "population": 0.02, "count": 0},
            "answer_object": {
                "answer": answer,
                "precipitation_concentration": {
                    "ratios_by_product": precip["ratios_by_product"],
                    "largest_product": precip["largest_product"],
                    "satellite_daily_max_gap_mm": precip["satellite_daily_max_gap_mm"],
                },
                "timing": timing,
                "facility_exposure": {
                    "likely_affected": facilities["likely_affected"],
                    "apparently_unaffected": facilities["apparently_unaffected"],
                    "total_listed": facilities["total_listed"],
                    "likely_fraction": facilities["likely_fraction"],
                    "likely_to_unaffected_ratio": facilities["likely_to_unaffected_ratio"],
                },
                "denominator_check": denominator,
                "decision": primary_gt["decision"],
            },
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_Locked_event_anchor_2024_Sudan_floods_and_Arba_at_Dam_flood.json",
                "data/other/other_003_01_NASA_Earth_Observatory_-_Floods_swamp_Sudan.html.html",
                "data/exposure_impact/exposure_impact_002_HDX_Sudan_Arbaat_flood_package_search.json",
                "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json",
                "data/physical_hazard/physical_hazard_002_ERA5-Land_hourly_aggregate_stats.json",
                "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
                "data/physical_hazard/physical_hazard_006_CHIRPS_daily_event_accumulated_precipitation.json",
            ],
        },
    }

    (Path(__file__).resolve().parent / "computed_gt.json").write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
